        "la2f": ["", "", "Accepted by this version but not described in the input documentation.", [], "", false, "undocumented"],
        "lambda": ["R", "1.d0", "parameter used for constrained_magnetization calculations N.B.: if the scf calculation does not converge, try to reduce lambda to obtain convergence, then restart the run with a larger lambda", [], "", false, ""],
        "lda_plus_u": ["", "", "Obsolete: still read by this version, which prints a warning, but no longer documented. See the HUBBARD card for the DFT+U inputs that replaced the Hubbard variables.", [], "", false, "obsolete"],
        "lda_plus_u_kind": ["", "", "Obsolete: still read by this version, which prints a warning, but no longer documented. See the HUBBARD card for the DFT+U inputs that replaced the Hubbard variables.", [], "", false, "obsolete"],
        "lforcet": ["L", "", "When starting a non collinear calculation using an existing density file from a collinear lsda calculation assumes previous density points in z direction and rotates it in the direction described by angle1 and angle2 variables for atomic type 1", [], "", false, ""],
        "lgcscf": ["L", ".FALSE.", "If .TRUE. perform a constant bias potential (constant-mu) calculation with Grand-Canonical SCF. (JCP 146, 114104 (2017), R.Sundararaman, et al.) NB: - The total energy displayed in output includes the potentiostat contribution (-mu*N).", [], "", false, ""],
        "localization_thr": ["R", "0.0", "Overlap threshold over which the exchange integral over a pair of localized orbitals is included in the evaluation of EXX operator. Any value greater than 0.0 triggers the SCDM localization and the evaluation on EXX using the localized orbitals.", [], "", false, ""],
        "london": ["L", ".FALSE.", "", [], "", false, ""],
        "london_c6": ["R", "standard Grimme-D2 values", "atomic C6 coefficient of each atom type ( if not specified default values from S. Grimme, J. Comp. Chem. 27, 1787 (2006), doi:10.1002/jcc.20495 are used; see file Modules/mm_dispersion.f90 )", [], "1:ntyp", false, ""],
        "london_rcut": ["R", "200", "cutoff radius (a.u.) for dispersion interactions", [], "", false, ""],
        "london_rvdw": ["R", "standard Grimme-D2 values", "atomic vdw radii of each atom type ( if not specified default values from S. Grimme, J. Comp. Chem. 27, 1787 (2006), doi:10.1002/jcc.20495 are used; see file Modules/mm_dispersion.f90 )", [], "1:ntyp", false, ""],
        "london_s6": ["R", "0.75", "global scaling parameter for DFT-D. Default is good for PBE.", [], "", false, ""],
        "lspinorb": ["L", "", "if .TRUE. the noncollinear code can use a pseudopotential with spin-orbit.", [], "", false, ""],
        "mbd_vdw": ["", "", "Accepted by this version but not described in the input documentation.", [], "", false, "undocumented"],
        "n_proj": ["", "", "Accepted by this version but not described in the input documentation.", [], "", false, "undocumented"],
        "nat": ["I", "", "number of atoms in the unit cell (ALL atoms, except if space_group is set, in which case, INEQUIVALENT atoms)", [], "", true, ""],
        "nbnd": ["I", "for an insulator, nbnd = number of valence bands (nbnd = # of electrons /2); for a metal, 20% more (minimum 4 more)", "Number of electronic states (bands) to be calculated. Note that in spin-polarized calculations the number of k-point, not the number of bands per k-point, is doubled", [], "", false, ""],
        "nbnd_cond": ["I", "nbnd_cond = nbnd - # of electrons / 2 in the collinear case; nbnd_cond = nbnd - # of electrons in the noncollinear case.", "Number of electronic states in the conduction manifold for a two chemical-potential calculation (twochem=.true.).", [], "", false, ""],
        "nelec_cond": ["R", "0.D0", "Number of electrons placed in the conduction manifold in a two-chemical potential calculation (twochem=.true.). Of the total # of electrons nelec, nelec-nelec_cond will occupy the valence manifold and nelec_cond will be constrained in the conduction manifold.", [], "", false, ""],
        "nextffield": ["I", "0", "Number of activated external ionic force fields. See Doc/ExternalForceFields.tex for further explanation and parameterizations", [], "", false, ""],
        "no_t_rev": ["L", ".FALSE.", "if (.TRUE.) disable the usage of magnetic symmetry operations that consist in a rotation + time reversal.", [], "", false, ""],
        "noinv": ["L", ".FALSE.", "if (.TRUE.) disable the usage of k => -k symmetry (time reversal) in k-point generation", [], "", false, ""],
        "noncolin": ["L", ".false.", "if .true. the program will perform a noncollinear calculation.", [], "", false, ""],
        "nosym": ["L", ".FALSE.", "if (.TRUE.) symmetry is not used. Consequences: - if a list of k points is provided in input, it is used \"as is\": symmetry-inequivalent k-points are not generated, and the charge density is not symmetrized;", [], "", false, ""],
        "nosym_evc": ["L", ".FALSE.", "if (.TRUE.) symmetry is not used, and k points are forced to have the symmetry of the Bravais lattice; an automatically generated Monkhorst-Pack grid will contain all points of the grid over the entire Brillouin Zone, plus the points rotated by the symmetries of the Bravais lattice which were not in the original grid.", [], "", false, ""],
        "nqx1": ["I", "", "Three-dimensional mesh for q (k1-k2) sampling of the Fock operator (EXX). Can be smaller than the number of k-points. Currently this defaults to the size of the k-point mesh used. In QE =< 5.0.2 it defaulted to nqx1=nqx2=nqx3=1.", [], "", false, ""],
        "nqx2": ["I", "", "Three-dimensional mesh for q (k1-k2) sampling of the Fock operator (EXX). Can be smaller than the number of k-points. Currently this defaults to the size of the k-point mesh used. In QE =< 5.0.2 it defaulted to nqx1=nqx2=nqx3=1.", [], "", false, ""],
        "nqx3": ["I", "", "Three-dimensional mesh for q (k1-k2) sampling of the Fock operator (EXX). Can be smaller than the number of k-points. Currently this defaults to the size of the k-point mesh used. In QE =< 5.0.2 it defaulted to nqx1=nqx2=nqx3=1.", [], "", false, ""],
        "nr1": ["I", "", "Three-dimensional FFT mesh (hard grid) for charge density (and scf potential). If not specified the grid is calculated based on the cutoff for charge density (see also ecutrho) Note: you must specify all three dimensions for this setting to be used.", [], "", false, ""],
        "nr1b": ["", "", "Accepted by this version but not described in the input documentation.", [], "", false, "undocumented"],
        "nr1s": ["I", "", "Three-dimensional mesh for wavefunction FFT and for the smooth part of charge density ( smooth grid ). Coincides with nr1, nr2, nr3 if ecutrho = 4 * ecutwfc ( default ) Note: you must specify all three dimensions for this setting to be used.", [], "", false, ""],
        "nr2": ["I", "", "Three-dimensional FFT mesh (hard grid) for charge density (and scf potential). If not specified the grid is calculated based on the cutoff for charge density (see also ecutrho) Note: you must specify all three dimensions for this setting to be used.", [], "", false, ""],
