        "nr3": ["I", "", "Three-dimensional FFT mesh (hard grid) for charge density (and scf potential). If not specified the grid is calculated based on the cutoff for charge density (see also ecutrho) Note: you must specify all three dimensions for this setting to be used.", [], "", false, ""],
        "nr3b": ["", "", "Accepted by this version but not described in the input documentation.", [], "", false, "undocumented"],
        "nr3s": ["I", "", "Three-dimensional mesh for wavefunction FFT and for the smooth part of charge density ( smooth grid ). Coincides with nr1, nr2, nr3 if ecutrho = 4 * ecutwfc ( default ) Note: you must specify all three dimensions for this setting to be used.", [], "", false, ""],
        "nscdm": ["", "", "Accepted by this version but not described in the input documentation.", [], "", false, "undocumented"],
        "nspin": ["I", "1", "nspin = 1 : non-polarized calculation (default) nspin = 2 : spin-polarized calculation, LSDA (magnetization along z axis) nspin = 4 : spin-polarized calculation, noncollinear (magnetization in generic direction) DO NOT specify nspin in this case; specify noncolin=.TRUE. instead", [], "", false, ""],
        "ntyp": ["I", "", "number of types of atoms in the unit cell", [], "", true, ""],
        "occupations": ["C", "", "How the electronic states are occupied: smearing (metals), tetrahedra, fixed (insulators) or from_input.", [["smearing","gaussian smearing for metals; see variables smearing and degauss"],["tetrahedra","Tetrahedron method, Bloechl's version: P.E. Bloechl, PRB 49, 16223 (1994) Requires uniform grid of k-points, to be automatically generated (see card K_POINTS)."],["tetrahedra_lin","Original linear tetrahedron method. To be used only as a reference; the optimized tetrahedron method is more efficient."],["tetrahedra_opt","Optimized tetrahedron method: see M. Kawamura, PRB 89, 094515 (2014). Can be used for phonon calculations as well."],["fixed","for insulators with a gap"],["from_input","The occupation are read from input file, card OCCUPATIONS. Option valid only for a single k-point, requires nbnd to be set in input."]], "", false, ""],
        "one_atom_occupations": ["L", ".FALSE.", "This flag is used for isolated atoms (nat=1) together with occupations='from_input'. If it is .TRUE., the wavefunctions are ordered as the atomic starting wavefunctions, independently from their eigenvalue. The occupations indicate which atomic states are filled.", [], "", false, ""],
        "origin_choice": ["I", "1", "Used only for space groups that in the ITA allow the use of two different origins. origin_choice=1, means the first origin, while origin_choice=2 is the second origin.", [], "", false, ""],
        "pol_type": ["C", "", "Type of polaron in gammaDFT.", [["e","electron polaron"],["h","hole polaron"]], "", false, ""],
        "q2sigma": ["R", "0.1", "ecfixed, qcutz, q2sigma: parameters for modified functional to be used in variable-cell molecular dynamics (or in stress calculation). \"ecfixed\" is the value (in Rydberg) of the constant-cutoff;", [], "", false, ""],
        "qcutz": ["R", "0.0", "", [], "", false, ""],
        "ref_alat": ["", "", "Accepted by this version but not described in the input documentation.", [], "", false, "undocumented"],
        "relaxz": ["L", ".FALSE.", "used only if gate = .TRUE. Allows the relaxation of the system towards the charged plate. Use carefully and utilize either a layer of fixed atoms or a potential barrier (block=.TRUE.) to avoid the atoms moving to the position of the plate or the dipole of the dipole correction (dipfield=.TRUE.).", [], "", false, ""],
        "report": ["I", "-1", "determines when atomic magnetic moments are printed on output: report = 0 never report =-1 at the beginning of the scf and at convergence report = N as -1, plus every N scf iterations", [], "", false, ""],
        "reserv": ["", "", "Accepted by this version but not described in the input documentation.", [], "", false, "undocumented"],
        "reserv_back": ["", "", "Accepted by this version but not described in the input documentation.", [], "", false, "undocumented"],
        "rhombohedral": ["L", ".TRUE.", "Used only for rhombohedral space groups. When .TRUE. the coordinates of the inequivalent atoms are given with respect to the rhombohedral axes, when .FALSE. the coordinates of the inequivalent atoms are given with respect to the hexagonal axes.", [], "", false, ""],
        "scdm": ["", "", "Accepted by this version but not described in the input documentation.", [], "", false, "undocumented"],
