        "smearing": ["C", "gaussian", "The smearing function, used with occupations = 'smearing'; the width is set by degauss.", [["gaussian","ordinary Gaussian spreading (Default)"],["gauss","ordinary Gaussian spreading (Default)"],["methfessel-paxton","Methfessel-Paxton first-order spreading (see PRB 40, 3616 (1989))."],["m-p","Methfessel-Paxton first-order spreading (see PRB 40, 3616 (1989))."],["mp","Methfessel-Paxton first-order spreading (see PRB 40, 3616 (1989))."],["marzari-vanderbilt","Marzari-Vanderbilt-DeVita-Payne cold smearing (see PRL 82, 3296 (1999))"],["cold","Marzari-Vanderbilt-DeVita-Payne cold smearing (see PRL 82, 3296 (1999))"],["m-v","Marzari-Vanderbilt-DeVita-Payne cold smearing (see PRL 82, 3296 (1999))"],["mv","Marzari-Vanderbilt-DeVita-Payne cold smearing (see PRL 82, 3296 (1999))"],["fermi-dirac","smearing with Fermi-Dirac function"],["f-d","smearing with Fermi-Dirac function"],["fd","smearing with Fermi-Dirac function"]], "", false, ""],
        "space_group": ["I", "0", "The number of the space group of the crystal, as given in the International Tables of Crystallography A (ITA). This allows to give in input only the inequivalent atomic positions. The positions of all the symmetry equivalent atoms are calculated by the code. Used only when the atomic positions are of type crystal_sg.", [], "", false, ""],
        "starting_charge": ["R", "0.0", "starting charge on atomic type 'i', to create starting potential with startingpot = 'atomic'.", [], "1:ntyp", false, ""],
        "starting_magnetization": ["R", "0", "Starting spin polarization on atomic type 'i' in a spin-polarized (LSDA or non-collinear/spin-orbit) calculation. The input values can have an absolute value greater than or equal to 1, which will be interpreted as the site's magnetic moment.", [], "1:ntyp", false, ""],
        "starting_ns_eigenvalue": ["R", "-1.d0 that means NOT SET", "In the first iteration of an DFT+U run it overwrites the m-th eigenvalue of the ns occupation matrix for the ispin component of atomic species ityp. For the noncollinear case, the ispin index runs up to npol=2 The value lmax is given by the maximum angular momentum number to which the Hubbard U is applied.", [], "1,1,1:2*lmax+1,nspin\\", false, ""],
        "starting_spin_angle": ["L", ".FALSE.", "In the spin-orbit case when domag=.TRUE., by default, the starting wavefunctions are initialized as in scalar relativistic noncollinear case without spin-orbit. By setting starting_spin_angle=.TRUE. this behaviour can be changed and the initial wavefunctions are radial functions multiplied by spin-angle functions.", [], "", false, ""],
        "step_pen": ["", "", "Accepted by this version but not described in the input documentation.", [], "", false, "undocumented"],
        "tot_charge": ["R", "0.0", "Total charge of the system. Useful for simulations with charged cells. By default the unit cell is assumed to be neutral (tot_charge=0). tot_charge=+1 means one electron missing from the system, tot_charge=-1 means one additional electron, and so on.", [], "", false, ""],
        "tot_magnetization": ["R", "-10000 [unspecified]", "Total majority spin charge - minority spin charge. Used to impose a specific total electronic magnetization. If unspecified then tot_magnetization variable is ignored and the amount of electronic magnetization is determined during the self-consistent cycle.", [], "", false, ""],
        "ts_vdw": ["", "", "Accepted by this version but not described in the input documentation.", [], "", false, "undocumented"],
