        "ts_vdw_isolated": ["L", ".FALSE.", "Optional: set it to .TRUE. when computing the Tkatchenko-Scheffler vdW energy or the Many-Body dispersion (MBD) energy for an isolated (non-periodic) system.", [], "", false, ""],
        "u_projection_type": ["", "", "Obsolete: still read by this version, which prints a warning, but no longer documented. See the HUBBARD card for the DFT+U inputs that replaced the Hubbard variables.", [], "", false, "obsolete"],
        "uniqueb": ["L", ".FALSE.", "Used only for monoclinic lattices. If .TRUE. the b unique ibrav (-12 or -13) are used, and symmetry equivalent positions are chosen assuming that the twofold axis or the mirror normal is parallel to the b axis. If .FALSE. it is parallel to the c axis.", [], "", false, ""],
        "use_all_frac": ["L", ".FALSE.", "if (.FALSE.) force real-space FFT grids to be commensurate with fractionary translations of non-symmorphic symmetry operations, if present (e.g.: if a fractional translation (0,0,c/4) exists, the FFT dimension along the c axis must be multiple of 4).", [], "", false, ""],
        "vdw_corr": ["C", "none", "Type of Van der Waals correction. Allowed values:", [["grimme-d2","Semiempirical Grimme's DFT-D2. Optional variables: london_s6, london_rcut, london_c6, london_rvdw S. Grimme, J. Comp. Chem."],["Grimme-D2","Semiempirical Grimme's DFT-D2. Optional variables: london_s6, london_rcut, london_c6, london_rvdw S. Grimme, J. Comp. Chem."],["DFT-D","Semiempirical Grimme's DFT-D2. Optional variables: london_s6, london_rcut, london_c6, london_rvdw S. Grimme, J. Comp. Chem."],["dft-d","Semiempirical Grimme's DFT-D2. Optional variables: london_s6, london_rcut, london_c6, london_rvdw S. Grimme, J. Comp. Chem."],["grimme-d3","Semiempirical Grimme's DFT-D3. Optional variables: dftd3_version, dftd3_threebody S. Grimme et al, J. Chem. Phys 132, 154104 (2010), doi:10.1063/1.3382344"],["Grimme-D3","Semiempirical Grimme's DFT-D3. Optional variables: dftd3_version, dftd3_threebody S. Grimme et al, J. Chem. Phys 132, 154104 (2010), doi:10.1063/1.3382344"],["DFT-D3","Semiempirical Grimme's DFT-D3. Optional variables: dftd3_version, dftd3_threebody S. Grimme et al, J. Chem. Phys 132, 154104 (2010), doi:10.1063/1.3382344"],["dft-d3","Semiempirical Grimme's DFT-D3. Optional variables: dftd3_version, dftd3_threebody S. Grimme et al, J. Chem. Phys 132, 154104 (2010), doi:10.1063/1.3382344"],["TS","Tkatchenko-Scheffler dispersion corrections with first-principle derived C6 coefficients. Optional variables: ts_vdw_econv_thr, ts_vdw_isolated See A."],["ts","Tkatchenko-Scheffler dispersion corrections with first-principle derived C6 coefficients. Optional variables: ts_vdw_econv_thr, ts_vdw_isolated See A."],["ts-vdw","Tkatchenko-Scheffler dispersion corrections with first-principle derived C6 coefficients. Optional variables: ts_vdw_econv_thr, ts_vdw_isolated See A."],["ts-vdW","Tkatchenko-Scheffler dispersion corrections with first-principle derived C6 coefficients. Optional variables: ts_vdw_econv_thr, ts_vdw_isolated See A."],["tkatchenko-scheffler","Tkatchenko-Scheffler dispersion corrections with first-principle derived C6 coefficients. Optional variables: ts_vdw_econv_thr, ts_vdw_isolated See A."],["MBD","Many-body dipersion (MBD) correction to long-range interactions. Optional variables: ts_vdw_isolated A. Ambrosetti, A. M. Reilly, R. A. DiStasio, A."],["mbd","Many-body dipersion (MBD) correction to long-range interactions. Optional variables: ts_vdw_isolated A. Ambrosetti, A. M. Reilly, R. A. DiStasio, A."],["many-body-dispersion","Many-body dipersion (MBD) correction to long-range interactions. Optional variables: ts_vdw_isolated A. Ambrosetti, A. M. Reilly, R. A. DiStasio, A."],["mbd_vdw","Many-body dipersion (MBD) correction to long-range interactions. Optional variables: ts_vdw_isolated A. Ambrosetti, A. M. Reilly, R. A. DiStasio, A."],["XDM","Exchange-hole dipole-moment model. Optional variables: xdm_a1, xdm_a2 A. D. Becke et al., J. Chem. Phys. 127, 154108 (2007), doi:10.1063/1.2795701 A."],["xdm","Exchange-hole dipole-moment model. Optional variables: xdm_a1, xdm_a2 A. D. Becke et al., J. Chem. Phys. 127, 154108 (2007), doi:10.1063/1.2795701 A."]], "", false, ""],
        "x_gamma_extrapolation": ["L", ".true.", "Specific for EXX. If .true., extrapolate the G=0 term of the potential (see README in examples/EXX_example for more) Set this to .false. for GAU-PBE.", [], "", false, ""],
        "xdm": ["L", ".FALSE.", "", [], "", false, ""],
        "xdm_a1": ["R", "0.6836", "Damping function parameter a1 (adimensional). It is NOT necessary to give a value if the functional is one of B86bPBE, PW86PBE, PBE, BLYP. For functionals in this list, the coefficients are given in: https://github.com/aoterodelaroza/postg/blob/master/xdm.param or https://erin-r-johnson.github.io/software/ A.", [], "", false, ""],
        "xdm_a2": ["R", "1.5045", "Damping function parameter a2 (angstrom). It is NOT necessary to give a value if the functional is one of B86bPBE, PW86PBE, PBE, BLYP. For functionals in this list, the coefficients are given in: https://github.com/aoterodelaroza/postg/blob/master/xdm.param or https://erin-r-johnson.github.io/software/ A.", [], "", false, ""],
        "yukawa": ["", "", "Accepted by this version but not described in the input documentation.", [], "", false, "undocumented"],
