        "conv_thr_init": ["R", "1.D-3", "When adaptive_thr = .TRUE. this is the convergence threshold used for the first scf cycle.", [], "", false, ""],
        "conv_thr_multi": ["R", "1.D-1", "When adaptive_thr = .TRUE. the convergence threshold for each scf cycle is given by: max( conv_thr, conv_thr_multi * dexx )", [], "", false, ""],
        "diago_cg_maxiter": ["I", "", "For conjugate gradient diagonalization: max number of iterations", [], "", false, ""],
        "diago_david_ndim": ["I", "2", "For Davidson diagonalization: dimension of workspace (number of wavefunction packets, at least 2 needed). A larger value may yield a smaller number of iterations in the algorithm but uses more memory and more CPU time in subspace diagonalization (cdiaghg/rdiaghg).", [], "", false, ""],
