        "diago_rmm_ndim": ["I", "4", "For RMM-DIIS diagonalization: dimension of workspace (number of wavefunction packets, at least 2 needed).", [], "", false, ""],
        "diago_thr_init": ["R", "", "Convergence threshold (ethr) for iterative diagonalization (the check is on eigenvalue convergence). For scf calculations: default is 1.D-2 if starting from a superposition of atomic orbitals; 1.D-5 if starting from a charge density.", [], "", false, ""],
        "diagonalization": ["C", "david", "", [["david","Davidson iterative diagonalization with overlap matrix (default). Fast, may in some rare cases fail."],["cg","Conjugate-gradient-like band-by-band diagonalization. MUCH slower than 'david' but uses less memory and is (a little bit) more robust."],["ppcg","PPCG iterative diagonalization"],["paro","ParO iterative diagonalization"],["ParO","ParO iterative diagonalization"],["rmm-davidson","RMM-DIIS iterative diagonalization. To stabilize the SCF loop RMM-DIIS is alternated with calls to Davidson or ParO solvers depending on the string used."],["rmm-paro","RMM-DIIS iterative diagonalization. To stabilize the SCF loop RMM-DIIS is alternated with calls to Davidson or ParO solvers depending on the string used."]], "", false, ""],
