    cards: {"ATOMIC_SPECIES":[],"ATOMIC_POSITIONS":["alat","bohr","angstrom","crystal","crystal_sg"],"K_POINTS":["tpiba","automatic","crystal","gamma","tpiba_b","crystal_b","tpiba_c","crystal_c"],"ADDITIONAL_K_POINTS":["tpiba","crystal","tpiba_b","crystal_b","tpiba_c","crystal_c"],"CELL_PARAMETERS":["alat","bohr","angstrom"],"CONSTRAINTS":[],"OCCUPATIONS":[],"ATOMIC_VELOCITIES":["a.u"],"ATOMIC_FORCES":[],"SOLVENTS":["1/cell","mol/L","g/cm^3"],"HUBBARD":["atomic","ortho-atomic","norm-atomic","wf","pseudo"]},
